  /** Renders a red asterisk after the label — purely visual, does not affect
   * validation (that's still driven by the schema / live field checks). */
  required?: boolean;
  /** Enables an in-field control for revealing or masking password text. */
  passwordVisibility?: {
    visible: boolean;
    onToggle: () => void;
  };
}
